window.docContents[37].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Semisimplicity-of-k_LSQ_G_RSQ_-implies-characteristic-does-not-divide-___G___/#Chapter4___Proposition4___1___2":{"contents":"Proposition 4.1.2. If k[G] is semisimple, then the characteristic of k does not divide |G|.\n\nProof. Write k[G] = \\bigoplus_{i=1}^r \\operatorname{End} V_i, where the V_i are irreducible representations and V_1 = k is the trivial 1-dimensional representation. Then\n\nk[G] = k \\oplus \\bigoplus_{i=2}^r \\operatorname{End} V_i = k \\oplus \\bigoplus_{i=2}^r d_i V_i,\nwhere d_i = \\dim V_i. By Schur's lemma,\n\n\\operatorname{Hom}_{k[G]}(k, k[G]) = k\\Lambda,\n\n\\operatorname{Hom}_{k[G]}(k[G], k) = k\\epsilon,\n\nfor nonzero homomorphisms of representations \\epsilon : k[G] \\to k and \\Lambda : k \\to k[G] unique up to scaling. We can take \\epsilon such that \\epsilon(g) = 1 for all g \\in G, and we can take \\Lambda such that \\Lambda(1) = \\sum_{g \\in G} g. Then\n\n\\epsilon \\circ \\Lambda(1) = \\epsilon\\left(\\sum_{g \\in G} g\\right) = \\sum_{g \\in G} 1 = |G|.\n\nIf |G| = 0, then \\Lambda has no left inverse, as (a\\epsilon) \\circ \\Lambda(1) = 0 for any a \\in k. This is a contradiction. \\square\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.1. Maschke's theorem\tSemisimplicity of k[G] implies characteristic does not divide |G|","header":"Semisimplicity of k[G] implies characteristic does not divide |G|","id":"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Semisimplicity-of-k_LSQ_G_RSQ_-implies-characteristic-does-not-divide-___G___/#Chapter4___Proposition4___1___2"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Irreducible-subrepresentation-existence/#Chapter2___Problem2___3___15":{"contents":"Problem 2.3.15. Let V be a nonzero finite dimensional representation of an algebra A. Show that it has an irreducible subrepresentation. Then show by example that this does not always hold for infinite dimensional representations.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tIrreducible subrepresentation existence","header":"Irreducible subrepresentation existence","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Irreducible-subrepresentation-existence/#Chapter2___Problem2___3___15"},"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Faithful-representation/#Chapter2___Definition2___7___3":{"contents":"Definition 2.7.3. A representation \\rho : A \\to \\operatorname{End} V of an algebra A is faithful if \\rho is injective.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.7. Examples of algebras\tFaithful representation","header":"Faithful representation","id":"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Faithful-representation/#Chapter2___Definition2___7___3"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map/#Chapter2___Discussion_2___9_heading___heading-1":{"contents":"Let \\mathfrak{g} be a vector space over a field k, and let [\\ ,\\ ] : \\mathfrak{g} \\times \\mathfrak{g} \\longrightarrow \\mathfrak{g} be a skew-symmetric bilinear map. (That is, [a, a] = 0, and hence [a, b] = -[b, a].)\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tSection 2.9: Lie algebras — heading and skew-symmetric bilinear map","header":"2.9. Lie algebras","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map/#Chapter2___Discussion_2___9_heading___heading-1"},"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/#chapter-06___section-6-2":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations","header":"6.2. Indecomposable representations of the quivers $A_1$, $A_2$, $A_3$","id":"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/#chapter-06___section-6-2"}});
